"""Allocated-range reporting for sink files."""

import os

from . import _winapi
from ._support import as_path, require_existing_file
from ._winapi import FILE_ATTRIBUTE_NORMAL, GENERIC_READ, OPEN_EXISTING, SPARSE_ATTRIBUTE
from .errors import WSParseError


def _normalise(ranges, size):
    """Clamp, order and merge ``ranges`` so the result is a clean partition."""
    cleaned = []
    for offset, length in ranges:
        if length <= 0 or offset >= size:
            continue
        if offset < 0:
            length += offset
            offset = 0
            if length <= 0:
                continue
        if offset + length > size:
            length = size - offset
        if length > 0:
            cleaned.append((offset, length))
    cleaned.sort(key=lambda item: item[0])
    merged = []
    for offset, length in cleaned:
        if merged:
            previous_offset, previous_length = merged[-1]
            previous_end = previous_offset + previous_length
            if offset <= previous_end:
                end = max(previous_end, offset + length)
                merged[-1] = (previous_offset, end - previous_offset)
                continue
        merged.append((offset, length))
    return merged


def _ranges_windows(path, size, sparse):
    handle = _winapi.open_handle(
        path, GENERIC_READ, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL
    )
    with handle:
        try:
            raw = _winapi.query_allocated_ranges(handle, size)
        except WSParseError as exc:
            # A file system that does not implement the sparse FSCTLs at all
            # cannot have holes either, so everything in such a file is backed
            # by clusters.  A sparse file that fails the query is a real error.
            if exc.kind == "unsupported" and not sparse:
                return [(0, size)]
            raise
    return raw


def _ranges_posix(path, size):
    # Development convenience only; see the note in :mod:`wsparse.alloc`.
    seek_data = getattr(os, "SEEK_DATA", None)
    seek_hole = getattr(os, "SEEK_HOLE", None)
    if seek_data is None or seek_hole is None:
        return [(0, size)]
    try:
        fd = os.open(path, os.O_RDONLY)
    except OSError as exc:
        raise WSParseError(str(exc), kind="os", path=path) from exc
    found = []
    try:
        offset = 0
        while offset < size:
            try:
                start = os.lseek(fd, offset, seek_data)
            except OSError:
                break
            if start >= size:
                break
            end = os.lseek(fd, start, seek_hole)
            if end <= start:
                break
            found.append((start, min(end, size) - start))
            offset = end
    finally:
        os.close(fd)
    return found


def allocated_ranges(path):
    """Return ``[(offset, length), ...]`` of the byte ranges backed by clusters.

    The transfer layer uses this to decide which parts of a sink still have to
    be fetched: a range that is already allocated is on disk, everything else
    is a hole that still needs data.  The list is ordered by ``offset``, the
    ranges never overlap, and every range lies inside the file's logical
    length.

    A file that is nothing but holes reports an empty list; a file with no
    holes at all reports a single range covering its whole length.
    """
    path = as_path(path)
    info = require_existing_file(path)
    size = info.st_size
    if size == 0:
        return []
    sparse = bool(getattr(info, "st_file_attributes", 0) & SPARSE_ATTRIBUTE)
    if _winapi.is_windows():
        raw = _ranges_windows(path, size, sparse)
    else:
        raw = _ranges_posix(path, size)
    return _normalise(raw, size)

